with a as(select * from public.authors where open_library_id=any(array['OL22019A','OL863535A','OL934457A','OL24452A','OL3203001A','OL3505784A','OL8715660A','OL88547A']::text[]) or id=any(array[620,421,710,3119]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789032502997','9789032004682','9789021012292','9789024568529','9789492928283','9789029508483']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL134888W','OL267636W','OL14873505W','OL18020257W','OL24326597W','OL972173W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['gardenofshadows','schaduwenindetuin','asterixlegionnaire','asterixenhet1stelegioen','asterixthelegionary','asterixandthelegionary','onedayatatime','elkedagisereendruk4','elkedagisereen','prodigalson','verlorenzoon','welkominhetrijkderzieken','dekleineblondedood']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['gardenofshadows','schaduwenindetuin','asterixlegionnaire','asterixenhet1stelegioen','asterixthelegionary','asterixandthelegionary','onedayatatime','elkedagisereendruk4','elkedagisereen','prodigalson','verlorenzoon','welkominhetrijkderzieken','dekleineblondedood']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987118001 and 987118999),'editions',(select count(*) from public.editions where id between 987218001 and 987218999),'authors',(select count(*) from public.authors where id between 987318001 and 987318999))) as preflight;
